//! Target SQL dialect and export error types.

use std::fmt;
use std::str::FromStr;

/// Target SQL dialect for DDL generation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SqlDialect {
    /// PostgreSQL (`"ident"`, `CREATE TYPE ... AS ENUM`, `GENERATED BY DEFAULT AS IDENTITY`).
    Postgres,
    /// MySQL (`` `ident` ``, inline `ENUM(...)`, `AUTO_INCREMENT`).
    Mysql,
    /// SQLite (`"ident"`, `CHECK (...)`, inline `FOREIGN KEY`).
    Sqlite,
    /// Microsoft SQL Server / T-SQL (`[ident]`, `IDENTITY(1,1)`, `NVARCHAR(MAX)`).
    SqlServer,
    /// Oracle Database (`"ident"`, `VARCHAR2`, `NUMBER`, `CLOB`).
    Oracle,
}

impl SqlDialect {
    /// Canonical lowercase dialect identifier.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Postgres => "postgres",
            Self::Mysql => "mysql",
            Self::Sqlite => "sqlite",
            Self::SqlServer => "sqlserver",
            Self::Oracle => "oracle",
        }
    }
}

impl fmt::Display for SqlDialect {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl FromStr for SqlDialect {
    type Err = SqlExportError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let low = s.trim().to_ascii_lowercase();
        match low.as_str() {
            "postgres" | "postgresql" | "pg" => Ok(Self::Postgres),
            "mysql" => Ok(Self::Mysql),
            "sqlite" | "sqlite3" => Ok(Self::Sqlite),
            "sqlserver" | "mssql" | "tsql" => Ok(Self::SqlServer),
            "oracle" | "ora" => Ok(Self::Oracle),
            _ => Err(SqlExportError::UnknownDialect(s.trim().to_string())),
        }
    }
}

/// Error returned when SQL DDL export configuration is invalid.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SqlExportError {
    /// The requested SQL dialect name is not recognized.
    UnknownDialect(String),
}

impl fmt::Display for SqlExportError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::UnknownDialect(d) => write!(
                f,
                "unknown SQL dialect `{d}` (expected: postgres, mysql, sqlite, sqlserver, oracle)"
            ),
        }
    }
}

impl std::error::Error for SqlExportError {}
